import 'package:flutter/material.dart';
enum IncomeRange { under2500, from2500To5000, from5000To8000, over8000, preferNotToSay }
enum FixedCostShareRange { underHalf, aboutHalf, overHalf, unsure, preferNotToSay }
enum PlanningPriority { breathingRoom, upcomingCost, reduceSpending, debtOrganisation, explore }
class PlanRangeScreen extends StatefulWidget { const PlanRangeScreen({super.key,required this.onKeep,required this.onExact}); final VoidCallback onKeep,onExact; @override State<PlanRangeScreen> createState()=>_PlanRangeScreenState(); }
class _PlanRangeScreenState extends State<PlanRangeScreen> { IncomeRange? income; FixedCostShareRange? costs; PlanningPriority? priority; @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Plan with ranges')),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[DropdownButton<IncomeRange>(hint:const Text('Income range'),value:income,items:IncomeRange.values.map((v)=>DropdownMenuItem(value:v,child:Text(v.name))).toList(),onChanged:(v)=>setState(()=>income=v)),DropdownButton<FixedCostShareRange>(hint:const Text('Fixed-cost share'),value:costs,items:FixedCostShareRange.values.map((v)=>DropdownMenuItem(value:v,child:Text(v.name))).toList(),onChanged:(v)=>setState(()=>costs=v)),DropdownButton<PlanningPriority>(hint:const Text('Planning priority'),value:priority,items:PlanningPriority.values.map((v)=>DropdownMenuItem(value:v,child:Text(v.name))).toList(),onChanged:(v)=>setState(()=>priority=v)),const SizedBox(height:16),Text('Snapshot: ${income?.name ?? 'not selected'}; ${costs?.name ?? 'not selected'}; ${priority?.name ?? 'not selected'}. No exact dollar targets are calculated.'),const Spacer(),OutlinedButton(onPressed:widget.onKeep,child:const Text('Keep this range-based snapshot')),FilledButton(onPressed:widget.onExact,child:const Text('Use exact numbers for a daily calculation'))]))); }
